$string['settings:rag_return_scope'] = 'Skop pemulangan dapatan semula';
$string['settings:rag_return_scope_desc'] = 'Apa yang disisipkan untuk setiap hasil yang ditemui. "chunk" (default) menyisipkan cebisan ~400 perkataan yang sepadan. "window" menyisipkan cebisan yang sepadan berserta cebisan bersebelahan daripada halaman yang sama. "page" menyisipkan keseluruhan halaman modul tempat padanan itu berada. window/page membantu apabila jawapan merentasi satu halaman, dengan kos gesaan (prompt) yang lebih besar.';
$string['settings:rag_window_size'] = 'Saiz tetingkap dapatan semula';
