$string['settings:csp_mode_enforce'] = 'Kuatkuasa (sekat muatan luar senarai benar)';
// v4.5.0: site-wide pedagogy defaults.
$string['settings:pedagogy_defaults_heading'] = 'Lalai pedagogi';
$string['settings:pedagogy_defaults_heading_desc'] = 'Keadaan lalai seluruh tapak bagi setiap ciri pedagogi. Hidupkan satu ciri di sini dan setiap kursus mewarisinya melainkan kursus itu mempunyai tindihan eksplisit pada halaman tetapan kursus [[tutorshort]]nya (paksa hidup / paksa mati). Apabila menaik taraf ke v4.5.0, setiap tindihan "paksa mati" setiap kursus yang ditetapkan kepada nilai lama mati-secara-lalai <code>0</code> dikosongkan supaya lalai global baharu berkuat kuasa dengan bersih. Mati secara lalai — naik taraf daripada v4.4.x tidak mengubah apa-apa sehingga pentadbir menghidupkan sesuatu ciri.';
$string['pedagogy:mastery'] = 'Penjejakan penguasaan hidup secara lalai';
$string['pedagogy:mastery_desc'] = 'Apabila hidup, setiap kursus mewarisi penjejakan penguasaan melainkan kursus itu mempunyai penggantiannya sendiri. Penguasaan memerlukan objektif pembelajaran yang dikurasi — kursus tanpa objektif berundur dengan baik, tiada ralat.';
