$string['coursesettings:apibaseurl_rejected'] = 'URL asas API tidak disimpan: ia mestilah titik akhir HTTPS awam yang lulus pemeriksaan keselamatan SSRF.';
$string['settings:escalation_intent_patterns'] = 'Corak niat eskalasi';
$string['settings:escalation_intent_patterns_desc'] = 'PCRE, no delimiters. Satu ungkapan biasa setiap baris; baris yang bermula dengan # diabaikan. Tiket sokongan hanya dibuka apabila mesej pelajar sendiri sepadan dengan salah satu corak ini, supaya kandungan kursus tidak boleh mencetuskan eskalasi bagi pihak pelajar. Biarkan kosong untuk menggunakan nilai lalai terbina dalam, yang merangkumi bahasa Inggeris serta beberapa ungkapan lazim dalam bahasa Sepanyol, Perancis, Jerman dan Portugis. Tapak yang pelajarnya menulis dalam bahasa lain patut menambah corak di sini: mesej yang tidak sepadan bermakna tiada tiket dibuka.';
$string['settings:zendesk_require_consent'] = 'Perlukan kebenaran sebelum peningkatan sokongan';
$string['settings:zendesk_require_consent_desc'] = 'Apabila dihidupkan (disyorkan), [[tutorshort]] meningkatkan perbualan ke meja sokongan Zendesk hanya selepas pelajar menerima notis kebenaran larian pertama, yang mendedahkan bahawa meminta bantuan manusia berkongsi perbualan (termasuk nama dan e-mel) dengan sokongan. Matikan ini hanya jika anda memperoleh kebenaran itu dengan cara lain; dengan ia dimatikan, peningkatan dihantar serta-merta. Tiada kesan melainkan peningkatan Zendesk didayakan.';
$string['chat:escalation_needs_consent'] = 'Nampaknya ini memerlukan ahli pasukan sokongan kami. Untuk menyerahkannya kepada mereka, saya perlu berkongsi perbualan ini, termasuk nama dan e-mel anda, dengan meja sokongan. Anda belum bersetuju dengan itu lagi, jadi saya tidak menghantar apa-apa. Jika anda mahukan bantuan manusia, sila terima notis perkongsian data untuk pembantu ini dan tanya semula, atau hubungi sokongan secara terus.';
$string['privacy:metadata:email_optout'] = 'Keutamaan menarik diri e-mel setiap penerima (jenis e-mel yang penerima telah berhenti melanggan).';
$string['privacy:metadata:email_optout:email'] = 'Alamat e-mel penerima yang penarikan diri itu terpakai.';
$string['privacy:metadata:email_optout:optout_type'] = 'Jenis e-mel yang penerima telah menarik diri.';
$string['privacy:metadata:email_optout:userid'] = 'Pengguna Moodle yang penarikan diri itu dimiliki, apabila diketahui.';
$string['chat:consent_scroll_hint'] = 'Sila tatal ke bawah untuk membaca notis penuh sebelum meneruskan.';
$string['settings:rag_min_similarity'] = 'Relevans Minimum (kosinus)';
$string['settings:rag_min_similarity_desc'] = 'Buang ketulan yang diperoleh yang persamaan kosinusnya dengan soalan berada di bawah nilai ini, supaya soalan yang tersasar daripada topik atau kurang maklumat menyisipkan lebih sedikit (atau sifar) petikan dan bukannya sentiasa memenuhi hingga Top-K dengan padanan yang lemah. Julat 0 hingga 1; 0 melumpuhkan get ini. Nilai yang betul bergantung pada model embedding: 0.25 sesuai untuk text-embedding-3-small. Naikkan untuk lebih ketat (kurang konteks, lebih tepat pada topik), turunkan untuk lebih longgar.';
$string['settings:rag_currentpage_boost'] = 'Galakan Halaman Semasa';
$string['settings:rag_currentpage_boost_desc'] = 'Bonus kecil yang ditambah pada skor relevans ketulan daripada halaman yang sedang dilihat pelajar, supaya soalan seperti "terangkan ini" mengutamakan halaman yang kelihatan apabila skornya hampir sama. Penyusunan sahaja: ia tidak memaksa ketulan halaman yang tidak relevan melepasi get relevans minimum. Tetapkan 0 untuk melumpuhkan.';
$string['settings:history_mode'] = 'Mod Pemilihan Sejarah';
$string['settings:history_mode_desc'] = 'Cara giliran perbualan lalu dipilih sebelum dihantar ke model. <strong>Semantik</strong> hanya mengekalkan giliran terkini yang relevan dengan soalan semasa (dan sentiasa pertukaran terkini), supaya giliran terdahulu yang lapuk dan tersasar daripada topik tidak membengkakkan kos atau menyimpangkan jawapan; ia membuat satu panggilan embedding tambahan setiap mesej. <strong>Keterkinian</strong> mengekalkan pasangan "Max Conversation History" terakhir tanpa mengira relevans (kelakuan lama, tiada panggilan tambahan). Jika embedding tidak tersedia, mod semantik kembali kepada keterkinian secara automatik.';
$string['settings:history_mode_semantic'] = 'Semantik (giliran terkini yang relevan)';
$string['settings:history_mode_recency'] = 'Keterkinian (N pasangan terakhir)';
$string['settings:history_semantic_minscore'] = 'Had Bawah Relevans Sejarah (kosinus)';
$string['settings:history_semantic_minscore_desc'] = 'Dalam mod sejarah semantik, giliran lalu hanya dikekalkan jika persamaannya dengan soalan semasa sekurang-kurangnya nilai ini (pertukaran terkini sentiasa dikekalkan). Julat 0 hingga 1; bergantung pada model. Naikkan untuk lebih ketat (kurang sejarah), turunkan untuk mengekalkan lebih banyak.';
$string['settings:history_candidates'] = 'Tetingkap Calon Sejarah';
$string['settings:history_candidates_desc'] = 'Dalam mod sejarah semantik, hanya pasangan terkini sebanyak ini diberi skor relevans (had kos). Pasangan yang lebih lama daripada tetingkap ini tidak dihantar. Kekalkan nilai ini pada atau melebihi "Max Conversation History".';

