$string['settings:embed_provider_voyage'] = 'Voyage AI (voyage-3.5 — disyorkan; +4 MTEB berbanding OpenAI 3-small, konteks 4x, pelbagai bahasa)';
$string['settings:rerank_heading'] = 'RAG: Pengambilan dua peringkat (pemeringkatan semula)';
$string['settings:rerank_heading_desc'] = 'Peringkat pengambilan kedua yang pilihan: persamaan kosinus memilih N kepingan calon teratas (lalai 50), kemudian pengsukor silang-pengekod menilai setiap pasangan (pertanyaan, kepingan) dan K terbaik masuk ke dalam prompt. Mati secara lalai; jatuh kembali ke kosinus satu peringkat jika pemeringkat semula tidak dikonfigurasi atau gagal.';
$string['settings:rerank_enabled'] = 'Pengambilan dua peringkat (Voyage rerank-2.5)';
$string['settings:rerank_enabled_desc'] = 'Apabila didayakan, pengambilan RAG menjadi dua peringkat: persamaan kosinus memulangkan N calon teratas (lalai 50), kemudian pengekod silang Voyage rerank-2.5 menilai setiap satu dan K teratas masuk ke dalam prompt. Peningkatan yang diterbitkan: +15 Recall@10 perusahaan, +39% NDCG BEIR. Pengebilan ~$0.05/MTok. Memerlukan <code>rerank_apikey</code> di bawah; jatuh kembali secara elegan ke kosinus satu peringkat jika pemeringkat semula gagal atau tidak dikonfigurasi.';
$string['settings:rerank_apikey'] = 'Kunci API pemeringkat semula';
$string['settings:rerank_apikey_desc'] = 'Kunci API Voyage AI untuk rerank-2.5. Biarkan kosong untuk menggunakan semula Kunci API Penyematan di atas (penggunaan Voyage biasa berkongsi satu kunci merentas sematan + pemeringkat semula).';
$string['settings:rerank_model'] = 'Model pemeringkat semula';
$string['settings:rerank_model_desc'] = 'Lalai <code>rerank-2.5</code>. Model pemeringkat semula Voyage yang lebih baru boleh ditentukan di sini.';
$string['settings:rerank_apibaseurl'] = 'URL asas API pemeringkat semula';
$string['settings:rerank_apibaseurl_desc'] = 'Gantikan URL asas pemeringkat semula Voyage. Biarkan kosong untuk menggunakan URL Asas API Penyematan di atas, atau lalai Voyage (<code>https://api.voyageai.com/v1</code>).';
$string['settings:rerank_candidates'] = 'Tetingkap calon pemeringkat semula';
$string['settings:rerank_candidates_desc'] = 'Berapa banyak calon kosinus top-N yang masuk ke peringkat penyusunan semula. Lalai 20. Diukur pada 1,008 pertanyaan: 20 menyamai 30 pada recall (R@3 89.0% berbanding 89.3%) dengan kos sepertiga lebih rendah, manakala 50 berkos 2.5 kali lebih tinggi tanpa keuntungan yang boleh diukur. Di bawah 10 recall merosot. Kos meningkat secara linear dengan nilai ini.';
$string['settings:stt_selfhosted_heading'] = 'Transkripsi hos sendiri (Whisper)';
$string['settings:stt_selfhosted_heading_desc'] = 'Jalankan ucapan-ke-teks pada perkakasan anda sendiri tanpa kos seminit. Arahkan [[tutorshort]] ke mana-mana pelayan transkripsi serasi OpenAI: Docker <code>whisper-server</code>, <code>speaches</code> (faster-whisper), atau pelayan <code>whisper.cpp</code>. Apabila URL pelayan ditetapkan di sini ia menjadi laluan STT lalai; pilih penyedia berbayar dalam Penyedia STT Aktif di atas untuk mengatasi. Jika pelayan berada pada rangkaian peribadi atau http biasa, tambah juga hosnya ke senarai benar titik akhir dipercayai SSRF dalam bahagian Keselamatan.';
$string['settings:stt_selfhosted_url'] = 'URL pelayan STT hos sendiri';
$string['settings:stt_selfhosted_url_desc'] = 'URL asas pelayan transkripsi serasi OpenAI, contohnya <code>http://10.0.0.5:8000</code>. [[tutorshort]] menambah <code>/v1/audio/transcriptions</code> secara automatik; laluan titik akhir penuh juga diterima. Biarkan kosong untuk melumpuhkan STT hos sendiri.';
$string['settings:stt_selfhosted_model'] = 'Model STT hos sendiri';
$string['settings:stt_selfhosted_model_desc'] = 'Nama model yang dihantar ke pelayan, sepadan dengan model Whisper yang dimuatnya — contohnya <code>Systran/faster-whisper-small</code> untuk speaches atau <code>large-v3</code>. Biarkan kosong untuk menghantar <code>whisper-1</code>, yang diterima atau diabaikan oleh kebanyakan pelayan hos sendiri.';
