$string['settings:spend_cap_per_course_default'] = 'Had perbelanjaan lalai setiap kursus (USD)';
$string['settings:spend_cap_per_course_default_desc'] = 'Had defensif yang digunakan pada setiap kursus yang tidak mempunyai had perbelanjaan setiap kursus sendiri yang dikonfigurasi. Tetapkan kepada cth. <code>30</code> untuk mengehadkan perbelanjaan bulanan mana-mana kursus tunggal kepada $30 tanpa perlu menala kursus individu. <code>0</code> = tiada lalai (hanya had seluruh laman dan gantian setiap kursus yang digunakan). Apabila kursus melepasi 80% / 95% / 100% had ini, saluran paip peringatan spend-guard sedia ada menghantar pemberitahuan pentadbir (senarai penerima: <code>spend_notify_emails</code>, jatuh kembali ke pentadbir laman). Kursus tertentu sentiasa boleh menaikkan siling sendiri dengan menetapkan gantian setiap kursus yang lebih tinggi.';
$string['settings:premium_escalation_heading'] = 'Peringkat eskalasi premium (A.10)';
$string['settings:premium_escalation_heading_desc'] = 'Penghalaan pilihan setiap giliran ke model premium (Claude Opus 4.8 secara lalai) untuk prompt di mana peringkat sembang workhorse bergelut dengan ketara — biasanya matematik berbilang langkah, CS, dan penaakulan sains. Diselesaikan oleh bake-off A.10 2026-06-09: Opus 4.8 menang pada 14.97/15 berbanding gpt-4o 12.68/15 pada prompt sukar. Dua laluan pencetus: padanan regex pada mesej pengguna, ATAU senarai benar kursus yang mengeskot setiap giliran. Mati secara lalai. Pada ~5% eskalasi, jangkakan ~$700/bulan pada 100k MAU [[unishort]] di atas perbelanjaan sembang asas.';
$string['settings:premium_escalation_enabled'] = 'Dayakan penghalaan eskalasi premium';
$string['settings:premium_escalation_enabled_desc'] = 'Apabila dihidupkan, penghala setiap giliran menyemak senarai regex pencetus dan senarai benar kursus untuk setiap panggilan sembang; giliran yang sepadan dihalakan ke penyedia premium. Jatuh kembali ke penyedia workhorse jika baris premium tiada atau gagal diinstansiasi. Gantian pemilih LLM pentadbir sentiasa menang tanpa mengira.';
$string['settings:premium_escalation_provider'] = 'Penyedia premium';
$string['settings:premium_escalation_provider_desc'] = 'ID penyedia untuk menghalakan panggilan premium. Mesti sepadan dengan baris dalam penyedia Perbandingan (supaya kunci API, URL asas, dan suhu datang dari tempat yang sama yang sudah diurus pentadbir). Lalai <code>claude</code>.';
$string['settings:premium_escalation_model'] = 'Model premium';
$string['settings:premium_escalation_model_desc'] = 'Nama model yang dihantar ke penyedia premium. Lalai <code>claude-sonnet-5</code> mengikut keputusan bake-off A.10.';
$string['settings:premium_escalation_triggers'] = 'Regex pencetus premium';
$string['settings:premium_escalation_triggers_desc'] = 'Satu regex PCRE setiap baris (tanpa pembatas; padanan tidak sensitif huruf besar kecil digunakan secara automatik). Baris bermula dengan # adalah ulasan. Biarkan kosong untuk menggunakan set lalai yang dipilih dari bake-off A.10 (penanda STEM berbilang langkah: "derive", "prove that", "step by step", matematik LaTeX, blok kod berpagar, big-O, kamiran, pengoptimuman, dsb.).';
$string['settings:premium_escalation_course_tags'] = 'Senarai benar kursus premium';
$string['settings:premium_escalation_course_tags_desc'] = 'Satu nama pendek kursus atau awalan nombor id setiap baris. Setiap giliran dalam kursus yang sepadan dieskot secara automatik tanpa mengira regex mesej (gunakan untuk kursus berat STEM di mana eskalasi sepatutnya menjadi lalai). Padanan adalah awalan tidak sensitif huruf besar kecil — "MATH" sepadan dengan MATH121, MATH205, dsb.';
$string['settings:cost_anomaly_heading'] = 'Pengesan anomali kos (v6.0)';
$string['settings:cost_anomaly_heading_desc'] = 'Tugas berjadual harian (<code>cost_anomaly_check</code>) yang membandingkan perbelanjaan [[tutorshort]] seluruh laman hari ini dengan median bergerak 7 hari. Menghantar e-mel ke senarai penerima <code>spend_notify_emails</code> (jatuh kembali ke pentadbir laman) apabila hari ini melebihi pengganda yang dikonfigurasi × median. Menangkap tiga mod kegagalan yang terlepas oleh ambang had perbelanjaan 80% / 95% / 100% sedia ada: (1) kursus liar di mana siling mutlak tidak dilanggar tetapi kursus tunggal tiba-tiba memacu 10x volum biasanya, (2) mendayakan peringkat premium secara tidak sengaja, (3) salah haluan penyedia. Mati secara lalai; setara dalam-[[tutorshort]] bagi pertanyaan Redash di <code>.drafts/sola-redash-cost-anomaly-2026-06-09.md</code>.';
$string['settings:cost_anomaly_enabled'] = 'Dayakan pengesan anomali kos';
$string['settings:cost_anomaly_enabled_desc'] = 'Apabila dihidupkan, tugas berjadual harian menilai perbelanjaan hari ini berbanding median bergerak 7 hari dan menghantar e-mel kepada pentadbir pada anomali. 7 hari pertama selepas mendayakan menghasilkan status <code>insufficient_history</code> (tiada garis asas sejarah lagi) dan tidak pernah mengeluarkan amaran. Idempoten setiap hari: bendera dalam <code>config_plugins</code> menghentikan e-mel berulang jika cron berjalan beberapa kali.';
$string['settings:cost_anomaly_multiplier'] = 'Pengganda anomali';
$string['settings:cost_anomaly_multiplier_desc'] = 'Perbelanjaan hari ini mesti melebihi pengganda ini × median 7 hari untuk mencetuskan amaran. Lalai <code>2.0</code>. Turunkan ke <code>1.5</code> untuk amaran awal (lebih banyak positif palsu semasa lonjakan pendaftaran). Naikkan ke <code>3.0</code> jika penggunaan [[unishort]] cukup tidak menentu sehingga lonjakan 2x menjadi rutin.';
$string['settings:prompt_debug_enabled'] = 'Log prompt sistem yang dirakit ke fail';
$string['settings:prompt_debug_enabled_desc'] = 'Apabila dihidupkan, setiap giliran sembang menulis prompt sistem penuh yang dirakit dan kiraan aksara setiap bahagian ke <code>moodledata/temp/sola_prompt_debug.log</code> (bergolek pada ~1MB). Mati secara lalai. Gunakan untuk mengukur saiz prompt secara empirikal dan mengaudit bahagian mana yang menyumbang token paling banyak. Log mengandungi prompt sistem sahaja (tiada input pelajar atau PII).';
