$string['settings:hidden_categories'] = 'Kategori kursus tersembunyi';
$string['settings:hidden_categories_desc'] = 'Senarai nama atau ID kategori kursus yang dipisahkan koma, di mana pembantu tidak sepatutnya muncul. Contoh: "Pembangunan kursus, 42". Pembantu juga disembunyikan secara automatik apabila mod suntingan dihidupkan.';
$string['settings:provider_heading'] = 'Pembekal AI dan perbualan';
$string['settings:provider_heading_desc'] = 'Konfigurasikan platform AI, model dan tingkah laku dalam perbualan.';
$string['settings:claude_temperature_allow_prefixes'] = 'Model Claude yang menyokong parameter temperature';
$string['settings:claude_temperature_allow_prefixes_desc'] = 'Satu awalan nama model setiap baris. Model Anthropic yang namanya bermula dengan salah satu daripadanya masih menerima parameter pensampelan <code>temperature</code>. Bagi mana-mana model Claude yang tidak sepadan dengan sebarang awalan, temperature ditinggalkan (model penaakulan bermula Opus 4.7 menolaknya dengan ralat HTTP 400). Biarkan kosong untuk menggunakan nilai lalai yang disertakan bersama pemalam.';
$string['settings:max_tokens'] = 'Panjang jawapan maksimum (token)';
$string['settings:max_tokens_desc'] = 'Bilangan token maksimum bagi setiap jawapan AI. Nilai lebih rendah menghasilkan jawapan yang lebih ringkas dan pantas. 512 = lebih kurang 2-3 ayat, 1024 = lebih kurang 1-2 perenggan, 2048 = penerangan yang lebih panjang. Tetapkan 0 untuk tiada had (nilai lalai pembekal digunakan).';
$string['settings:profile_update_interval'] = 'Selang kemas kini profil pelajar';
$string['settings:profile_update_interval_desc'] = 'Selepas bilangan mesej pelajar ini dalam sesuatu kursus, pembantu akan membina (atau menyegarkan) profil pembelajaran yang merumuskan kekuatan, kelemahan, gaya belajar dan minat. Profil ini disertakan dalam gesaan sistem untuk jawapan yang diperibadikan. Tetapkan 0 untuk melumpuhkannya. Lalai: 10.';
$string['settings:enable_thinking'] = 'Penaakulan lanjutan (Claude sahaja)';
$string['settings:enable_thinking_desc'] = 'Menghidupkan penaakulan mudah suai bagi model Claude. Claude sendiri menentukan bila dan sejauh mana ia memikirkan sesuatu masalah sebelum menjawab. Meningkatkan ketepatan bagi soalan rumit, tetapi menambah penggunaan token dan kelewatan. Kandungan penaakulan tidak dipaparkan kepada pelajar. Pembekal lain mengabaikan tetapan ini.';
$string['settings:rag_sources_heading'] = 'Sumber kandungan RAG';
$string['settings:rag_sources_heading_desc'] = 'Pilih jenis kandungan kursus yang teksnya akan diekstrak oleh pengindeks RAG. Penunjuk status di <a href="{$a}">halaman pentadbiran RAG</a> menunjukkan sama ada setiap pengekstrak mempunyai keperluan untuk berfungsi (contohnya alat pdftotext atau senarai benarkan Cloudflare).';
$string['settings:rag_extract_pdf'] = 'Indeks fail PDF (mod_resource)';
$string['settings:rag_extract_pdf_desc'] = 'Mengekstrak teks daripada fail PDF yang dimuat naik melalui alat <code>pdftotext</code> (poppler). Laluan alat dikesan secara automatik; nyatakan di bawah jika perlu.';
$string['settings:rag_pdftotext_path'] = 'Laluan alat pdftotext';
$string['settings:rag_pdftotext_path_desc'] = 'Biarkan kosong untuk pengesanan automatik (memeriksa <code>/usr/bin/pdftotext</code>, <code>/usr/local/bin/pdftotext</code> dan <code>which pdftotext</code>). Isi hanya jika pemasangan anda berada di tempat lain.';
$string['settings:rag_extract_docx'] = 'Indeks fail DOCX (mod_resource)';
$string['settings:rag_extract_docx_desc'] = 'Mengekstrak teks daripada dokumen Word yang dimuat naik menggunakan ZipArchive PHP. Tiada kebergantungan luaran diperlukan.';
$string['settings:rag_extract_pptx'] = 'Indeks fail PPTX (mod_resource)';
$string['settings:rag_extract_pptx_desc'] = 'Mengekstrak teks daripada pembentangan PowerPoint moden yang dimuat naik menggunakan ZipArchive PHP. Menyusuri XML slaid dan nota penyampai mengikut susunan slaid; tiada kebergantungan luaran diperlukan. Fail binari <code>.ppt</code> lama tidak disokong — simpan semula pembentangan tersebut sebagai <code>.pptx</code>.';
$string['settings:rag_extract_h5p'] = 'Indeks kandungan H5P (mod_h5p)';
$string['settings:rag_extract_h5p_desc'] = 'Menyusuri JSON kandungan H5P dan mengindeks semua medan yang mengandungi teks (soalan, jawapan, maklum balas, penerangan). Metadata jenis kandungan H5P agak luas; beberapa padanan tersilap boleh berlaku dalam kes sempadan.';
$string['settings:rag_extract_scorm'] = 'Indeks pakej SCORM (mod_scorm)';
$string['settings:rag_extract_scorm_desc'] = 'Menyahzip pakej SCORM dan mengindeks <code>imsmanifest.xml</code>, semua fail <code>.html</code> serta rentetan kandungan Articulate Storyline. <strong>Dilumpuhkan secara lalai</strong> kerana pemprosesan SCORM boleh menelan kos tinggi. Saiz pakej maksimum ditetapkan oleh <code>rag_scorm_max_mb</code>.';
$string['settings:rag_scorm_max_mb'] = 'Saiz pakej SCORM maksimum untuk diindeks (MB)';
$string['settings:rag_scorm_max_mb_desc'] = 'Melangkau pakej SCORM yang lebih besar daripada nilai ini bagi mengelakkan penggunaan memori berlebihan.';
$string['settings:rag_fetch_transcripts'] = 'Ambil transkrip bagi video dan kandungan interaktif terbenam';
$string['settings:rag_fetch_transcripts_desc'] = 'Mengimbas kandungan mod_page dan mod_book untuk mencari iframe terbenam (Synthesia, YouTube, Articulate, Genially) dan mengambil alamat transkrip yang mengiringi setiap benaman (mencari di atas dan di bawah bingkai). Memerlukan sambungan HTTPS keluar daripada pelayan ini ke hos transkrip. <strong>Dilumpuhkan secara lalai</strong>; hidupkan selepas pembekal transkrip menambah pelayan ini ke dalam senarai benarkannya (contohnya melalui peraturan Cloudflare berasaskan IP).';
$string['settings:rag_iframe_host_patterns'] = 'Corak hos iframe';
$string['settings:rag_iframe_host_patterns_desc'] = 'Satu ungkapan biasa setiap baris yang dipadankan dengan atribut <code>src</code> sesuatu iframe. Setiap bingkai yang sepadan dianggap sebagai benaman interaktif yang transkripnya perlu dipadankan dan diindeks. Baris yang bermula dengan <code>#</code> ialah komen.';
$string['settings:rag_transcript_url_pattern'] = 'Corak alamat transkrip';
$string['settings:rag_transcript_url_pattern_desc'] = 'Ungkapan biasa yang dipadankan dengan alamat pautan transkrip. Bagi setiap iframe yang dikesan, pengindeks memilih pautan sepadan yang terdekat (di atas atau di bawahnya) lalu memadankannya. Biarkan kosong untuk melumpuhkan pemadanan transkrip.';
$string['settings:performance_heading'] = 'Prestasi';
