$string['settings:spend_guard_heading'] = 'Perlindungan perbelanjaan dan pengoptimum';
$string['settings:spend_guard_heading_desc'] = 'Tetapkan had perbelanjaan LLM bagi setiap tempoh. Apabila had dicapai, [[tutorshort]] menggantung permintaan atau beralih kepada pembekal yang lebih murah dalam rantaian sandaran anda. Lihat <a href="{$a}">halaman Kos token</a> untuk status perbelanjaan semasa dan saranan pengoptimum.';
