$string['settings:bench_default_samples'] = 'Prompt setiap larian';
$string['settings:bench_default_samples_desc'] = 'Berapa banyak prompt dihantar oleh satu penanda aras yang dibaris gilirkan dari web. Setiap prompt menelan dua panggilan model secara langsung — jawapan dan hakim — jadi ini ialah dail kos. Dihadkan pada 50 dalam kod, yang merupakan saiz set emas dan juga yang mengekalkan satu larian di dalam had kadar pembekal.';
$string['settings:bench_heading'] = 'Penanda aras model';
$string['settings:bench_heading_desc'] = 'Satu larian penanda aras menjawab 50 prompt dan meminta satu model hakim memarkahkan setiap jawapan terhadap satu rubrik, kemudian menyimpan satu baris: min rubrik, kos setiap panggilan, dan masa ke bait pertama. Larian dibaris gilirkan dari halaman registri model dan dilaksanakan oleh cron.';
$string['settings:bench_judge_model'] = 'Model hakim';
$string['settings:bench_judge_model_desc'] = 'Model yang memarkahkan jawapan. Menukarnya menukar makna setiap skor yang diambil selepas itu, sebab itulah setiap larian merekodkan hakim yang digunakannya dan keluaran pemalam semasa ia berjalan.';
$string['settings:bench_judge_provider'] = 'Pembekal hakim';
$string['settings:bench_judge_provider_desc'] = 'Pembekal bagi model yang memarkahkan jawapan. Kekalkan ia di luar kumpulan peserta: satu model tidak boleh menggredkan dirinya sendiri.';
$string['settings:bench_min_quality_n'] = 'Aras kebolehbandingan (item bermarkah)';
$string['settings:bench_min_quality_n_desc'] = 'Bilangan paling sedikit item bermarkah yang boleh dimiliki oleh satu larian tersimpan dan masih dibandingkan dengan satu larian lain. Larian di bawah aras itu dikekalkan dan ditunjukkan, dilabelkan sebagai rujukan sahaja, jadi satu larian smoke tiga prompt tidak sekali-kali boleh mengatasi satu keputusan lima puluh prompt. Biarkan pada 0 untuk menggunakan lalai terbina; aras 0 akan mengalahkan pengawal ini.';
$string['settings:embed_input_type_asymmetric'] = 'Tak simetri pertanyaan/dokumen (disyorkan)';
$string['settings:embed_input_type_mode'] = 'Jenis input embedding';
$string['settings:embed_input_type_mode_desc'] = 'Untuk embedding Voyage sahaja. Voyage memproyeksikan teks secara berbeza bergantung sama ada ia pertanyaan atau dokumen. "Tak simetri" menghantar input_type=query semasa mendapatkan semula dan input_type=document semasa mengindeks. Itulah yang dimaksudkan vendor dan itulah yang terukur paling baik pada korpus ini: menggunakan proyeksi dokumen di sebelah pertanyaan merugikan 30,8 mata peratusan recall dan kalah dalam setiap julat panjang pertanyaan (2026-08-21, voyage-3.5, set berbentuk pengeluaran). "Ruang dikongsi" menghantar input_type=document di kedua-dua belah; ia mendapatkan semula dengan ketara lebih teruk dan wujud hanya sebagai insurans migrasi, kerana satu proyeksi membolehkan model pertanyaan ditukar tanpa membenamkan semula korpus. Pilih tak simetri melainkan anda berada di tengah-tengah migrasi. Menukar tetapan ini tidak memerlukan pengindeksan semula: hanya proyeksi sebelah pertanyaan yang berubah. Ini BUKAN pemadanan model tak simetri (mengindeks dengan model Voyage yang lebih besar daripada yang anda gunakan untuk bertanya) — itu teknik berbeza yang dua kali gagal dihasilkan semula pada korpus ini, dan ia dikawal oleh tetapan model pertanyaan, bukan oleh tetapan ini.';
$string['settings:embed_input_type_shared'] = 'Ruang dikongsi (insurans migrasi; mendapatkan semula lebih teruk)';
$string['settings:embed_migration_heading'] = 'Migrasi model embedding';
$string['settings:embed_migration_heading_desc'] = 'Menukar model embedding atau lebarnya membatalkan setiap vektor tersimpan: pengambil enggan memarkahkan satu pertanyaan terhadap bongkah daripada satu ruang embedding yang berbeza, jadi satu kursus tidak mengambil apa-apa dan bukan mengambil secara buruk. Tetapan ini menerangkan model yang anda sedang berpindah KEPADANYA. Kursus kemudian di-embed semula satu demi satu dari halaman indeks RAG, menulis vektor baharu bersebelahan dengan yang lama, dan tetapan langsung di atas terus menyajikan pengambilan sehingga anda menukarnya sendiri.';
$string['settings:embed_migration_provider_inherit'] = 'Guna pembekal yang dikonfigurasi di atas';
$string['settings:embed_migration_target_apikey'] = 'Kunci API pembekal sasaran';
$string['settings:embed_migration_target_apikey_desc'] = 'Hanya diperlukan apabila pembekal sasaran berbeza daripada yang dikonfigurasi di atas. Kosong bermaksud guna kunci embedding yang ada.';
$string['settings:embed_migration_target_dimensions'] = 'Lebar embedding sasaran';
$string['settings:embed_migration_target_dimensions_desc'] = 'Lebar vektor untuk diminta semasa migrasi. 0 bermaksud lebar asli model. Voyage menerima 256, 512, 1024 dan 2048; satu lebar yang tidak ditawarkan oleh model ditinggalkan daripada permintaan dan bukan dihantar, yang akan memberi anda lebar asli secara senyap dan bukan yang anda minta.';
$string['settings:embed_migration_target_model'] = 'Model embedding sasaran';
$string['settings:embed_migration_target_model_desc'] = 'Nama model untuk meng-embed semasa migrasi, contohnya <code>voyage-4-large</code>. Kosong bermaksud tiada migrasi dikonfigurasi dan halaman indeks RAG tidak menawarkan apa-apa.';
$string['settings:embed_migration_target_provider'] = 'Pembekal embedding sasaran';
$string['settings:embed_migration_target_provider_desc'] = 'Biarkan kosong untuk memigrasikan dalam pembekal yang sudah dikonfigurasi di atas.';
$string['settings:rerank_min_query_chars'] = 'Rerank: panjang pertanyaan minimum';
$string['settings:rerank_min_query_chars_desc'] = 'Langkau pemeringkat semula bagi pertanyaan sepanjang bilangan aksara ini atau lebih pendek. Pertanyaan pendek berbentuk kata kunci dan pemeringkat semula hampir tidak menambah apa-apa berbanding persamaan kosinus pada dua atau tiga perkataan. Diukur pada set fikstur RAG: mengehadkan pada 50 mencatat 67.7% recall berbanding 67.2% untuk sentiasa hidup, pada kira-kira satu pertiga kos. Tetapkan kepada 0 untuk memeringkat semula setiap pertanyaan. Pemeringkatan semula yang dilangkau direkodkan dalam log mesej sebagai "[Rerank skipped: short_query]" supaya anda boleh mengesahkan get itu berfungsi.';
$string['settings:spend_export_key'] = 'Kunci eksport perbelanjaan';
$string['settings:spend_export_key_desc'] = 'Kunci Bearer bagi titik akhir eksport perbelanjaan AI bulanan di <code>/local/ai_course_assistant/spend_export.php</code>, yang ditarik oleh papan pemuka perbelanjaan sekali sebulan. Biarkan kosong untuk mematikan titik akhir itu — ia kemudian memulangkan 404 kepada setiap permintaan. Kunci itu diterima HANYA dalam pengepala <code>Authorization: Bearer</code>, tidak sekali-kali dalam URL. Jana satu nilai rawak yang panjang; sesiapa yang memegangnya boleh membaca perbelanjaan AI seluruh tapak. Setiap eksport yang berjaya direkodkan dalam log audit pemalam.';
